xml.Script:
        clRed     := 'FF0000';
        clYellow  := 'FFFF00';
        clGreen   := '33AA00';
        clDeepSky := '00BFFF';
        clBlack   := '333333';
        clSilver  := 'AAAAAA';

        K := 0.6;

        s2 := sqrt(2);
        A := ( 1 - s2 + sqrt(2 * s2 - 1)) / 2;
        B := (-1 + s2 + sqrt(2 * s2 - 1)) / 2;

        Ang := Arcsin(A);

        R1 := K * 0.50;
        R2 := K * 0.41;
        R3 := K * 0.30;
        R4 := K * 0.21;
        N := 40;
        for i := 0 to N - 1 do begin
            An := 2*Pi / N * i;
            sa := sin(An);
            ca := cos(An);
            x1[i] := R1 * ca;
            y1[i] := R1 * sa;
            x2[i] := R2 * ca;
            y2[i] := R2 * sa;
            x3[i] := R3 * ca;
            y3[i] := R3 * sa;
            x4[i] := R4 * ca;
            y4[i] := R4 * sa;
        end;

        D1 := K * 0.7;
        D2 := K * 0.86;
        D3 := D1 * sqrt(3) / (A + B);

        qA := (2 - 4 * s2);
        qB := D1 * 4 * sqrt(6 * s2 - 3);
        qC := (6 - 4 * s2) * R4 ^ 2 - 6 * D1 ^ 2 ;

        D4 := (-qB - sqrt(qB ^ 2 - 4 * qA * qC)) / (2 * qA);

        DCut1 := D1 - K * 0.1;
        DCut2 := D2 - K * 0.1;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

